"""
m2_models.utils
~~~~~~~~~~~~~~~
Metric calculations and data utilities for M2 Candidate Classification.
Ensures observation-level Top-1 accuracy, candidate miss-rate, Macro F1,
precision, recall, log loss, and route continuity metrics.
"""

import time
import numpy as np
import pandas as pd
from sklearn.metrics import (
    accuracy_score,
    precision_score,
    recall_score,
    f1_score,
    log_loss,
    confusion_matrix,
)

# Canonical 16 feature columns generated by M1
FEATURE_COLUMNS = [
    "dist",
    "dist_rank",
    "dist_gap",
    "dist_ratio",
    "heading_diff",
    "heading_cos",
    "heading_valid",
    "speed",
    "dist_prev",
    "dist_next",
    "overshoot",
    "arc_len",
    "next_choices",
    "two_way",
    "n_cand",
    "fallback",
]

# Features requiring standardization (for Linear, Kernel, & Neural models)
SCALED_MODELS = {"Logistic Regression", "Support Vector Machine", "MLP Classifier"}


def load_dataset(parquet_path: str, filter_reliable: bool = True):
    """
    Load candidate dataset from parquet file.
    Optionally filters label_reliable == 1 for clean training data.
    """
    df = pd.read_parquet(parquet_path)
    if filter_reliable and "label_reliable" in df.columns:
        df = df[df["label_reliable"] == 1].copy()
    return df


def compute_observation_top1(df_eval: pd.DataFrame, pred_probs: np.ndarray) -> float:
    """
    Computes observation-level Top-1 Accuracy:
    For each (trip_id, point_idx), select the candidate with the highest predicted score.
    Returns the percentage of observations where the selected candidate is correct (label == 1).
    """
    df_temp = df_eval[["trip_id", "point_idx", "label"]].copy()
    df_temp["score"] = pred_probs

    # Group by observation and pick candidate with max score
    # In case of ties, take the first
    idx_top1 = df_temp.groupby(["trip_id", "point_idx"])["score"].idxmax()
    top1_df = df_temp.loc[idx_top1]

    top1_acc = (top1_df["label"] == 1).mean()
    return float(top1_acc)


def compute_all_metrics(
    df_eval: pd.DataFrame,
    y_true: np.ndarray,
    pred_probs: np.ndarray,
    threshold: float = 0.5,
) -> dict:
    """
    Computes all standard candidate-level and observation-level metrics.
    """
    pred_labels = (pred_probs >= threshold).astype(int)
    
    # Clip probabilities for stable log loss
    eps = 1e-15
    pred_probs_clipped = np.clip(pred_probs, eps, 1 - eps)

    acc = accuracy_score(y_true, pred_labels)
    prec = precision_score(y_true, pred_labels, zero_division=0)
    rec = recall_score(y_true, pred_labels, zero_division=0)
    macro_f1 = f1_score(y_true, pred_labels, average="macro", zero_division=0)
    loss = log_loss(y_true, pred_probs_clipped)
    top1 = compute_observation_top1(df_eval, pred_probs)
    cm = confusion_matrix(y_true, pred_labels).tolist()

    return {
        "accuracy": float(acc),
        "precision": float(prec),
        "recall": float(rec),
        "macro_f1": float(macro_f1),
        "log_loss": float(loss),
        "top1_accuracy": float(top1),
        "confusion_matrix": cm,
    }


def compute_candidate_miss_rate(df_eval: pd.DataFrame) -> float:
    """
    Share of GPS observations whose aligned ground-truth arc is absent from their
    generated candidate set (i.e., max(label) == 0 for that (trip_id, point_idx)).
    """
    has_hit = df_eval.groupby(["trip_id", "point_idx"], sort=False)["label"].max()
    return float(1.0 - has_hit.mean())


def compute_point_continuity(df_eval: pd.DataFrame, pred_probs: np.ndarray) -> float:
    """
    Route continuity of classifier-only predictions (no HMM):
    for each trip, take each GPS point's highest-scoring candidate and compute the share of
    consecutive points whose predicted arcs are the same arc or directly connected
    (arc_to of the first == arc_from of the second). Returns the mean over trips.
    Same definition as m3_hmm.metrics.compute_pointwise_continuity.
    """
    df_temp = df_eval[["trip_id", "point_idx", "arc_id", "arc_from", "arc_to"]].copy()
    df_temp["score"] = pred_probs
    top = df_temp.loc[df_temp.groupby(["trip_id", "point_idx"])["score"].idxmax()]
    top = top.sort_values(["trip_id", "point_idx"])
    values = []
    for _, g in top.groupby("trip_id", sort=False):
        arc = g["arc_id"].to_numpy()
        a_from = g["arc_from"].to_numpy()
        a_to = g["arc_to"].to_numpy()
        if len(arc) < 2:
            continue
        ok = (arc[:-1] == arc[1:]) | (a_to[:-1] == a_from[1:])
        values.append(float(ok.mean()))
    return float(np.mean(values)) if values else float("nan")
